def transform(grid):
    n = len(grid)

    def rotate_cw(g):
        return [list(row) for row in zip(*g[::-1])]

    def rotate_ccw(g):
        return [list(row) for row in zip(*g)][::-1]

    def rotate_180(g):
        return [row[::-1] for row in g[::-1]]

    tiles = [
        [grid, rotate_cw(grid)],
        [rotate_ccw(grid), rotate_180(grid)],
    ]

    out = []
    for top, bottom in tiles:
        for r in range(n):
            out.append(top[r] + bottom[r])
    return out
